 "/faq": {
  "slug": "faq",
  "key": "faq",
  "t": "The Flat Rate Movers — FAQ — Questions, Answered",
  "d": "Frequently asked questions about flat-rate moving, SIR heavy-asset moves, ISPM 15 export packing, service areas, hours and the Short/Detailed quote toggle.",
  "c": "https://theflatratemovers.com/faq/",
  "og": "website",
  "img": "https://theflatratemovers.com/assets/img-02-0b80bbb82653.jpg",
  "imgSwapped": false,
  "ld": "{\"@context\":\"https://schema.org\",\"@graph\":[{\"@type\":\"WebPage\",\"@id\":\"https://theflatratemovers.com/faq/#webpage\",\"url\":\"https://theflatratemovers.com/faq/\",\"name\":\"The Flat Rate Movers — FAQ — Questions, Answered\",\"isPartOf\":{\"@id\":\"https://theflatratemovers.com/#website\"},\"about\":{\"@id\":\"https://theflatratemovers.com/#organization\"},\"inLanguage\":\"en-US\",\"datePublished\":\"2026-10-27\",\"dateModified\":\"2026-10-28\",\"description\":\"Frequently asked questions about flat-rate moving, SIR heavy-asset moves, ISPM 15 export packing, service areas, hours and the Short/Detailed quote toggle.\"},{\"@type\":\"BreadcrumbList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"name\":\"Home\",\"item\":\"https://theflatratemovers.com/\"},{\"@type\":\"ListItem\",\"position\":2,\"name\":\"FAQ — Questions, Answered\",\"item\":\"https://theflatratemovers.com/faq/\"}]},{\"@type\":\"FAQPage\",\"@id\":\"https://theflatratemovers.com/faq/#faq\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Is it really one flat rate?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Yes. Your move is quoted as one flat price, agreed in writing before move day — we do not bill by the hour. Our guarantee: Guaranteed Flat Rate or Your Move is Free!\"}},{\"@type\":\"Question\",\"name\":\"What weights need SIR?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Assets of 1,500 to 3,500 lbs — safes, medical devices, cryogenic equipment, pianos and antiques — are planned under SIR and the KIM-GS Protocol, with a floor-deflection check to L/360 before anything lifts.\"}},{\"@type\":\"Question\",\"name\":\"What is ISPM 15?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"The International Standards for Phytosanitary Measures No. 15 — the global rule for wood packaging in export. Our export crates are built from compliant, treated, marked wood so shipments clear customs.\"}},{\"@type\":\"Question\",\"name\":\"Where do you serve?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"From two home bases — Winchester, VA and Martinsburg, WV — across the Shenandoah Valley and Eastern Panhandle, with 16 published service areas from Winchester and 14 from Martinsburg, plus long-distance runs on I-81, I-66 and I-70. Full list on our Service Areas page.\"}},{\"@type\":\"Question\",\"name\":\"What are your hours?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Winchester (The Flat Rate Movers): Mon–Fri 8am–6pm, Sat 8am–4pm, Sun 9am–4pm. Martinsburg (Flat Rate Movers Martinsburg WV): Mon–Fri 9am–6pm, Sat 9am–4pm, Sun 9am–4pm. Phone +1-540-422-2153, email ratemovers@gmail.com.\"}},{\"@type\":\"Question\",\"name\":\"Short or Detailed quote?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Short (Quick Quote) is the default and is enough for most moves. Toggle Detailed on the quote button itself when your project needs full detail — nothing you typed is lost when you switch.\"}},{\"@type\":\"Question\",\"name\":\"Do you pack and crate?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Yes — full, partial and fragile-only packing and unpacking, custom crates, ISPM 15 export packing, loading, transloading and final-mile delivery.\"}},{\"@type\":\"Question\",\"name\":\"Do you move offices and industrial sites?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Yes — office moving, industrial offices, commercial, government and military relocations, planned around your operation and quoted flat in writing.\"}},{\"@type\":\"Question\",\"name\":\"How are you rated on Google?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Winchester: 5.0 from 1 review. Martinsburg: 4.7 from 6 reviews — listed per branch, never blended. Many high-value clients choose not to review, which we respect.\"}}]}]}",
  "jf": "faq.json"
 },
